func (b *Boom) worker(ch chan bool, wg *sync.WaitGroup) {
	defer wg.Done()
	// Pick one request from channel and process.
	for _ = range ch {
		s := time.Now()
		resp, err := b.Client.Do(b.Req)
		code := 0
